import javax.swing.*;import java.awt.*;import java.sql.*;
public class CandidateRegistration extends JFrame {
    String[] positions={"General Secretary","Sports Secretary","Vice President","Event Secretary"};JCheckBox[] checks=new JCheckBox[4];User user;
    public CandidateRegistration(JFrame owner,User u){user=u;setTitle("Candidate Registration");setSize(480,360);setLocationRelativeTo(owner);JPanel p=UI.panel();p.setLayout(new BoxLayout(p,BoxLayout.Y_AXIS));JLabel h=new JLabel("Select position(s)");h.setForeground(Color.WHITE);h.setFont(new Font("SansSerif",Font.BOLD,20));p.add(h);for(int i=0;i<4;i++){checks[i]=new JCheckBox(positions[i]);checks[i].setOpaque(false);checks[i].setForeground(Color.WHITE);p.add(checks[i]);}JButton save=UI.button("REGISTER"),close=UI.button("CLOSE");p.add(save);p.add(close);save.addActionListener(e->register());close.addActionListener(e->dispose());add(p);}
    private void register(){try{if("active".equals(UI.electionStatus())){UI.msg(this,"Registration is closed while election is active.");return;}int count=0;try(Connection c=DbConfig.connect()){c.setAutoCommit(false);try(PreparedStatement q=c.prepareStatement("SELECT COUNT(*) FROM Candidates WHERE student_id=?")){q.setString(1,user.id);try(ResultSet r=q.executeQuery()){r.next();if(r.getInt(1)>0){UI.msg(this,"You are already registered!");return;}}}try(PreparedStatement s=c.prepareStatement("INSERT INTO Candidates(student_id,position,candidate_name,votes) VALUES(?,?,?,0)")){for(int i=0;i<4;i++)if(checks[i].isSelected()){s.setString(1,user.id);s.setString(2,positions[i]);s.setString(3,user.name);s.addBatch();count++;}if(count==0){UI.msg(this,"Select at least one position.");return;}s.executeBatch();}c.commit();}UI.msg(this,"Candidate registration successful.");dispose();}catch(Exception e){UI.error(this,e);}}
}
